﻿Here is the complete Python code for generating, classifying, and mathematically auditing the **7×48 Parity Check Matrix (\\(H\\))** from your sources [1, 2]:


```python
import numpy as np


TOL = 1e-9
rng = np.random.default_rng(20261006)


# ==============================================================================
# MATRIX GENERATION
# Constructs a 7x48 binary parity matrix H from 48 selected 7-bit masks [2].
# Masks require odd parity (m & 1) and a bit weight >= 2 [2].
# ==============================================================================
def build_H():
    masks = [m for m in range(128) if (m & 1) and bin(m).count("1") >= 2][:48]
    H = np.array([[(m >> r) & 1 for m in masks] for r in range(7)], dtype=float)
    return H, masks


# ==============================================================================
# SYNDROME CLASSIFICATION
# Classifies syndrome vectors into "clean", "column", "axis", "rollback", or "refuse" [2].
# ==============================================================================
def classify(H, s):
    if np.linalg.norm(s) <= TOL:
        return ("clean",)
    sup = np.abs(s) > TOL
    col_hits = []
    for j in range(H.shape[1]):
        csup = H[:, j] > 0.5
        if np.array_equal(sup, csup):
            v = s[csup]
            if np.all(np.abs(v - v) <= TOL * max(1.0, abs(v))):
                col_hits.append((j, float(v)))
    axis = [
        k
        for k in range(H.shape)
        if np.array_equal(sup, np.arange(H.shape) == k)
    ]
    if len(col_hits) == 1 and not axis:
        j, c = col_hits
        if np.linalg.norm(s - c * H[:, j]) <= TOL * max(1.0, abs(c)):
            return ("column", j, c)
        return ("rollback",)
    if len(axis) == 1 and not col_hits:
        return ("axis", axis)
    return ("refuse",)


def is_col(r, j, e):
    return r == "column" and r[1] == j and abs(r[3] - e) <= 1e-9 * max(1.0, abs(e))


# ==============================================================================
# CODEC TEST BATTERY
# Verifies zero pair-sum collisions, single-error isolation, and refusal rules [4-6].
# ==============================================================================
def run_battery():
    H, masks = build_H()
    assert H.shape == (7, 48) [4]
    
    # Verify 48 distinct non-zero column vectors [4]
    cols = [tuple(H[:, j].astype(int)) for j in range(48)]
    assert len(set(cols)) == 48 [4]
    assert all(sum(c) >= 1 for c in cols) [4]
    
    # Assert pair-sum-free property (no two columns sum to a third) [4]
    bad = [
        (i, j, k)
        for i in range(48)
        for j in range(i + 1, 48)
        for k in range(48)
        if np.array_equal(H[:, i] + H[:, j], H[:, k])
    ]
    assert not bad, f"{len(bad)} pair-sum collisions" [4]


    # Test single-column noise injection across all 48 columns [5]
    for j in range(48):
        v = rng.normal(size=48)
        vp = v.copy()
        vp[j] += 3.7
        assert is_col(classify(H, H @ vp - H @ v), j, 3.7) [5]


    # Test 7 axis-shift error configurations [5]
    for k in range(7):
        v = rng.normal(size=48)
        t = H @ v
        s = H @ v - (t + 2.5 * np.eye(7)[k])
        assert classify(H, s) == ("axis", k) [5]


    # Enforce refusal for all 1,128 column-pair combinations [5, 6]
    n = 0
    for a in range(48):
        for b in range(a + 1, 48):
            v = rng.normal(size=48)
            vp = v.copy()
            vp[a] += 2.0
            vp[b] += 2.0
            if classify(H, H @ vp - H @ v) == ("refuse",):
                n += 1
    assert n == 1128, f"{n}/1128" [6]


    # Verify randomized double-error and triple-error refusal [6]
    for _ in range(200):
        v = rng.normal(size=48)
        j1, j2 = rng.choice(48, 2, replace=False)
        e1 = float(rng.uniform(0.5, 5))
        e2 = e1 + float(rng.uniform(0.3, 3))
        vp = v.copy()
        vp[j1] += e1
        vp[j2] += e2
        assert classify(H, H @ vp - H @ v) == ("refuse",) [6]


    for _ in range(200):
        v = rng.normal(size=48)
        js = rng.choice(48, 3, replace=False)
        e = float(rng.uniform(1, 5))
        vp = v.copy()
        for j in js:
            vp[j] += e
        assert classify(H, H @ vp - H @ v) == ("refuse",) [6]


    # Validate specific baseline relation [7]
    i11, i13, i9 = (masks.index(m) for m in (11, 13, 9))
    r = classify(H, H[:, i11] + H[:, i13] - H[:, i9])
    assert r == "column", "L1 example changed - re-audit needed" [7]


    return True


if __name__ == "__main__":
    if run_battery():
        print("Matrix generation and codec battery passed 100% of checks.")
